import { MeshPhysicalNodeMaterial } from 'three/webgpu';
import { uv, mix, vec2, vec3, texture, smoothstep, oneMinus, dot, sin, fract } from 'three/tsl';
import { gsap } from 'gsap';

export default function createNode(config, ctx) {
  const { THREE } = ctx;
  const colors = config?.intent?.visualSpec?.colors ?? {
    ink: '#16161d',
    paper: '#e8ecf2',
    accent: '#ff2a38',
    surface: '#0b0b10',
  };

  const group = new THREE.Group();
  group.name = 'features-card-3';

  const inner = new THREE.Group();
  group.add(inner);

  // ---- geometry: slight extrusion so the "flat rect" doctrine violation is avoided ----
  const width = 1.9;
  const height = 2.3;
  const depth = 0.07;
  const geometry = new THREE.BoxGeometry(width, height, depth, 1, 1, 1);

  // ---- color graph ----
  const inkVec = new THREE.Color(colors.ink);
  const surfaceVec = new THREE.Color(colors.surface);
  const accentVec = new THREE.Color(colors.accent);

  const uvNode = uv();

  function buildBaseColorNode(mapTexture) {
    const gradTop = vec3(inkVec.r, inkVec.g, inkVec.b);
    const gradBottom = vec3(surfaceVec.r, surfaceVec.g, surfaceVec.b);
    const gradient = mix(gradBottom, gradTop, uvNode.y);

    // procedural fine grain (subtle, <=4% amplitude)
    const grainRaw = fract(
      sin(dot(uvNode.mul(4000.0), vec2(12.9898, 78.233))).mul(43758.5453)
    );
    const grain = grainRaw.sub(0.5).mul(0.035);

    let base = gradient;
    if (mapTexture) {
      const texNode = texture(mapTexture, uvNode);
      base = mix(gradient, texNode.rgb, 0.62);
    }

    const withGrain = base.add(grain);

    // thin accent seam along bottom edge, kept under ~4% of surface height
    const accentColorNode = vec3(accentVec.r, accentVec.g, accentVec.b);
    const edgeMask = oneMinus(smoothstep(0.0, 0.035, uvNode.y));
    return mix(withGrain, accentColorNode, edgeMask.mul(0.55));
  }

  const material = new MeshPhysicalNodeMaterial();
  material.colorNode = buildBaseColorNode(null);
  material.metalness = 0.5;
  material.roughness = 0.56;
  material.clearcoat = 0.18;
  material.clearcoatRoughness = 0.32;
  if ('anisotropy' in material) material.anisotropy = 0.35;
  material.envMapIntensity = 1.0;

  const cardMesh = new THREE.Mesh(geometry, material);
  cardMesh.position.set(0, 0, 0);
  inner.add(cardMesh);

  // ---- rim / accent light, node-local only (scene already supplies ambient+key) ----
  const rimLight = new THREE.PointLight(colors.accent, 0.55, 6, 2);
  rimLight.position.set(1.1, 0.6, 1.6);
  group.add(rimLight);

  const backLight = new THREE.PointLight(colors.paper, 0.35, 5, 2);
  backLight.position.set(-1.0, 0.3, -1.2);
  group.add(backLight);

  // ---- texture load (async, cached) ----
  let loadedTexture = null;
  let disposed = false;
  const texPromise = config.imageUrl
    ? ctx.textureLoader.loadTexture(config.imageUrl).then((tex) => {
        if (disposed) return;
        loadedTexture = tex;
        tex.wrapS = THREE.RepeatWrapping;
        tex.wrapT = THREE.RepeatWrapping;
        tex.colorSpace = THREE.SRGBColorSpace;
        material.colorNode = buildBaseColorNode(tex);
        material.needsUpdate = true;
      })
    : Promise.resolve();

  // ---- weighted entrance settle ----
  inner.position.y = 0.32;
  inner.scale.setScalar(0.97);

  const entranceTl = gsap.timeline();
  entranceTl.to(inner.position, {
    y: 0,
    duration: 0.72,
    ease: 'power3.out',
  });
  entranceTl.to(
    inner.scale,
    { x: 1.04, y: 1.04, z: 1.04, duration: 0.42, ease: 'power2.out' },
    0.02
  );
  entranceTl.to(
    inner.scale,
    { x: 1, y: 1, z: 1, duration: 0.5, ease: 'power4.out' },
    0.44
  );

  // ---- idle: single slow breathing transform ----
  const idleTl = gsap.timeline({ repeat: -1, yoyo: true, delay: 1.3 });
  idleTl.to(inner.scale, {
    x: 1.015,
    y: 1.015,
    z: 1.015,
    duration: 3.2,
    ease: 'sine.inOut',
  });

  group.userData.handlers = {};

  group.userData.cleanup = () => {
    disposed = true;
    entranceTl.kill();
    idleTl.kill();
    gsap.killTweensOf(inner.position);
    gsap.killTweensOf(inner.scale);

    geometry.dispose();
    material.dispose();
    if (loadedTexture) loadedTexture.dispose();

    group.remove(rimLight);
    group.remove(backLight);
    rimLight.dispose?.();
    backLight.dispose?.();

    inner.remove(cardMesh);
    group.remove(inner);
  };

  return group;
}
